//
// Krita-authored oracles: OpenRaster files whose archives carry Krita's own rendering of the layer
// stack (`mergedimage.png`), generated by photocraft-corpus's `tools/krita-oracles/generate.py` and
// not bundled. Runs only with `KRITA_TEST_DIR` set (photocraft: `#[ignore]` + the same variable).

import Foundation
import PCDocument
import PCFoundation
import PCIOCore
import Testing
@testable import PCIO

@Suite struct KritaCorpusTests {
    init() { ExportSweep.install() }
    typealias Kit = FlatKit

    /// Files whose difference is known: the file, the share of pixels allowed outside the
    /// tolerance, and why. Everything else must match within the tolerance everywhere.
    static let known: [(String, Float, String)] = [
        ("blend-darker_color.ora", 0.02, "Krita weighs the channels differently when it picks the darker colour; near-ties pick the other pixel"),
        ("blend-lighter_color.ora", 0.02, "Krita weighs the channels differently when it picks the lighter colour; near-ties pick the other pixel"),
        ("blend-hard_mix_photoshop.ora", 0.02, "a channel sum of exactly 1 goes up in Photoshop's Hard Mix (ours) and down in Krita's"),
        ("depth-rgba-u16.ora", 1.0, "Krita blends this linear-light 16-bit document in linear light, but its ORA export stores sRGB 8-bit layers"),
    ]

    /// Largest premultiplied channel difference (0…1) between our composite and Krita's, the share
    /// of pixels over `tolerance`, and where the worst one is.
    static func maxError(_ doc: Document, _ oracle: Document, _ tolerance: Float) throws -> (Float, Float, String) {
        #expect(doc.size == oracle.size)
        let ours = try Kit.flatten(doc), theirs = try Kit.flatten(oracle)
        let w = doc.size.width
        var worst: (Float, String) = (0, "")
        var over = 0
        for (i, (a, b)) in zip(ours, theirs).enumerated() {
            let e = Kit.pixelError(a, b)
            if e > tolerance { over += 1 }
            if e > worst.0 {
                func q(_ p: SIMD4<Float>) -> [Int] { (0 ..< 4).map { Int((p[$0] * 255).rounded()) } }
                worst = (e, "at (\(i % w), \(i / w)): ours \(q(a)), Krita \(q(b))")
            }
        }
        return (worst.0, Float(over) / Float(max(ours.count, 1)), worst.1)
    }

    @Test(.enabled(if: ProcessInfo.processInfo.environment["KRITA_TEST_DIR"] != nil, "requires KRITA_TEST_DIR with Krita-authored .ora files"))
    func kritaOraFilesMatchTheirMergedImage() throws {
        let tolerance: Float = 3 / 255
        let root = URL(fileURLWithPath: try #require(ProcessInfo.processInfo.environment["KRITA_TEST_DIR"]))
        let paths = try FileManager.default.contentsOfDirectory(at: root, includingPropertiesForKeys: nil)
            .filter { $0.pathExtension.lowercased() == "ora" }.sorted { $0.path < $1.path }
        #expect(!paths.isEmpty, "no .ora files found")
        var passed = 0
        var failed: [String] = []
        for path in paths {
            let bytes = [UInt8](try Data(contentsOf: path))
            let name = path.lastPathComponent
            let r = try Kit.importFile(name, bytes)
            let merged = try Kit.importFile("mergedimage.png", try ZipReader(bytes).read(named: "mergedimage.png", max: 1 << 28)).document
            let (error, share, at) = try Self.maxError(r.document, merged, tolerance)
            // Saving as .pcraft keeps every imported layer exactly.
            let native = try Kit.export(r.document, "copy.pcraft")
            #expect(r.document.layers == (try Kit.importFile("copy.pcraft", native.bytes).document.layers), "\(name)")
            let known = Self.known.first { $0.0 == name }
            print("\(name): \(r.document.layers.count) layers, max error \(String(format: "%.2f", error * 255))/255 \(at)"
                + (known.map { String(format: " (%.1f%% of pixels; known: %@)", share * 100, $0.2) } ?? "")
                + (r.warnings.isEmpty ? "" : "\n    warnings: \(r.warnings.joined(separator: "; "))"))
            if error <= tolerance {
                passed += 1
            } else if known.map({ share > $0.1 }) ?? true {
                failed.append("\(name): \(String(format: "%.2f", error * 255))/255 on \(String(format: "%.2f", share * 100))% of pixels")
            }
        }
        print("\(passed)/\(paths.count) .ora files within \(String(format: "%.1f", tolerance * 255))/255")
        #expect(failed.isEmpty, "outside tolerance: \(failed)")
    }
}
